"""V2 COPY of baselines.py: reads data/training/pairs_v2.csv (corrected labels) and writes only to results_v2/. Generated by make_v2_scripts.py; do not edit."""
"""Baseline scores on real data (no model is trained or fitted).

Reads pairs_v1.csv + folds.json; writes results/baselines.csv, results/baselines.md
and results/baseline_scores.csv. Run from anywhere.
"""
from report_header import insert_header, labels_header  # run header for the report (captions only)
import json
from pathlib import Path

import numpy as np
import pandas as pd
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score

HERE = Path(__file__).resolve().parent
OUT = HERE / "results_v2"
OUT.mkdir(exist_ok=True)
N_BOOT, SEED, STAGE2_THRESHOLD = 1000, 0, 0.65

# ---- load: ids as strings, scores as floats ----
df = pd.read_csv(HERE / "pairs_v2.csv", dtype=str, keep_default_na=False)
folds = json.loads((HERE / "folds.json").read_text())["folds"]
need = ["lexical_score", "semantic_score", "containment", "label", "video_id", "pair_id", "is_synthetic"]
assert all(c in df.columns for c in need), "missing columns"

df = df[(df.is_synthetic == "0") & (df.label != "-1")].copy()   # real rows, no 'unsure'
for c in ["lexical_score", "semantic_score", "containment"]:
    df[c] = pd.to_numeric(df[c], errors="raise")
    assert df[c].notna().all(), f"NaN in {c}"
df["label"] = df.label.astype(int)
df["fold"] = df.video_id.map(folds).astype(int)
df = df.reset_index(drop=True)

# ---- baseline scores ----
df["lexical_only"] = df.lexical_score
df["semantic_only"] = df.semantic_score
df["current_stage2"] = 0.50 * df.semantic_score + 0.30 * df.lexical_score + 0.20 * df.containment
df["always_zero"] = 0.0
BASELINES = ["lexical_only", "semantic_only", "current_stage2", "always_zero"]


# ---- helpers ----
def recall_at_precision(y, s, p):
    """Max recall among operating points with precision >= p (0 if never reached)."""
    prec, rec, _ = precision_recall_curve(y, s)
    ok = prec >= p
    return float(rec[ok].max()) if ok.any() else 0.0


def best_f1_threshold(y, s):
    """Threshold maximising F1 on (y, s). Predict positive when score >= threshold."""
    prec, rec, thr = precision_recall_curve(y, s)
    f1 = 2 * prec[:-1] * rec[:-1] / np.clip(prec[:-1] + rec[:-1], 1e-12, None)
    return float(thr[np.argmax(f1)])


def prf(y, pred):
    tp = int(((pred == 1) & (y == 1)).sum())
    p = tp / pred.sum() if pred.sum() else 0.0
    r = tp / (y == 1).sum() if (y == 1).sum() else 0.0
    return p, r, (2 * p * r / (p + r) if p + r else 0.0)


def rank_metrics(y, s):
    """PR-AUC, ROC-AUC, recall@90/80 precision for one set of rows."""
    return {"pr_auc": average_precision_score(y, s),
            "roc_auc": roc_auc_score(y, s) if s.nunique() > 1 else 0.5,
            "recall_at_p90": recall_at_precision(y, s, 0.90),
            "recall_at_p80": recall_at_precision(y, s, 0.80)}


# ---- predictions at each baseline's operating point ----
# stage2: fixed 0.65. lexical/semantic: best-F1 threshold chosen on the OTHER folds.
# always_zero: predicts 0 everywhere.
thr_used = {}
for b in BASELINES:
    df[b + "_pred"] = 0
for f in sorted(df.fold.unique()):
    te, tr = df.fold == f, df.fold != f
    for b in ["lexical_only", "semantic_only"]:
        t = best_f1_threshold(df.loc[tr, "label"], df.loc[tr, b])
        thr_used[(b, f)] = t
        df.loc[te, b + "_pred"] = (df.loc[te, b] >= t).astype(int)
    thr_used[("current_stage2", f)] = STAGE2_THRESHOLD
df["current_stage2_pred"] = (df.current_stage2 >= STAGE2_THRESHOLD).astype(int)

# ---- metrics per scope ----
rows = []


def add(b, scope, metric, value):
    rows.append({"baseline": b, "scope": scope, "metric": metric, "value": value})


scopes = [("pooled", df)] + [(f"fold{f}", df[df.fold == f]) for f in sorted(df.fold.unique())]
for scope, g in scopes:
    y = g.label
    add("random_scorer", scope, "pr_auc", y.mean())            # floor = positive rate
    for b in BASELINES:
        add(b, scope, "n_rows", len(g))
        add(b, scope, "n_pos", int(y.sum()))
        for k, v in rank_metrics(y, g[b]).items():              # always_zero: constant score, AP = prevalence
            add(b, scope, k, v)
        p, r, f1 = prf(y.values, g[b + "_pred"].values)
        add(b, scope, "precision_at_op", p)
        add(b, scope, "recall_at_op", r)
        add(b, scope, "f1_at_op", f1)
        if scope != "pooled" and (b, int(scope[-1])) in thr_used:
            add(b, scope, "op_threshold", thr_used[(b, int(scope[-1]))])

# ---- bootstrap pooled PR-AUC, resampling whole videos ----
rng = np.random.default_rng(SEED)
vids = df.video_id.unique()
by_vid = {v: g for v, g in df.groupby("video_id")}
boot = {b: [] for b in BASELINES}
for _ in range(N_BOOT):
    samp = pd.concat([by_vid[v] for v in rng.choice(vids, len(vids), replace=True)])
    if samp.label.sum() == 0:
        continue
    for b in BASELINES:
        boot[b].append(average_precision_score(samp.label, samp[b]))
for b in BASELINES:
    lo, hi = np.percentile(boot[b], [2.5, 97.5])
    add(b, "pooled", "pr_auc_ci_low", lo)
    add(b, "pooled", "pr_auc_ci_high", hi)

res = pd.DataFrame(rows)
res.to_csv(OUT / "baselines.csv", index=False)
df[["pair_id", "video_id", "fold", "label"] + BASELINES].to_csv(OUT / "baseline_scores.csv", index=False)


# ---- markdown report ----
def val(b, scope, m):
    x = res[(res.baseline == b) & (res.scope == scope) & (res.metric == m)].value
    return float(x.iloc[0]) if len(x) else np.nan


scope_names = ["pooled", "fold1", "fold2", "fold3", "fold4"]
md = ["# Baseline results", "",
      f"Real rows only, label -1 excluded: {len(df)} rows, {int(df.label.sum())} positives, "
      f"{df.video_id.nunique()} videos. Nothing was trained. Lexical/semantic operating points use the "
      "best-F1 threshold from the other three folds; Stage 2 uses its fixed 0.65.", ""]


def table(title, metric):
    out = [f"### {title}", "", "| baseline | " + " | ".join(scope_names) + " |",
           "|---|" + "---|" * len(scope_names)]
    for b in BASELINES + (["random_scorer"] if metric == "pr_auc" else []):
        out.append(f"| {b} | " + " | ".join(f"{val(b, s, metric):.3f}" for s in scope_names) + " |")
    return out + [""]


md += table("PR-AUC (random_scorer = positive-rate floor)", "pr_auc")
md += ["Pooled PR-AUC 95% CI (1000 video-level bootstrap resamples, seed 0): " + "; ".join(
    f"{b} [{val(b, 'pooled', 'pr_auc_ci_low'):.3f}, {val(b, 'pooled', 'pr_auc_ci_high'):.3f}]"
    for b in BASELINES if b != "always_zero"), ""]
md += table("ROC-AUC", "roc_auc")
md += table("Recall at 90% precision", "recall_at_p90")
md += table("Recall at 80% precision", "recall_at_p80")
md += table("Precision at operating point", "precision_at_op")
md += table("Recall at operating point", "recall_at_op")
md += table("F1 at operating point", "f1_at_op")
md += ["### Thresholds used", "", "| baseline | fold1 | fold2 | fold3 | fold4 |", "|---|---|---|---|---|"]
for b in ["lexical_only", "semantic_only", "current_stage2"]:
    md.append(f"| {b} | " + " | ".join(f"{thr_used[(b, f)]:.3f}" for f in (1, 2, 3, 4)) + " |")

ranked = sorted([b for b in BASELINES if b != "always_zero"], key=lambda b: -val(b, "pooled", "pr_auc"))
best, second = ranked[0], ranked[1]
summ = [f"Best baseline by pooled PR-AUC: {best} ({val(best, 'pooled', 'pr_auc'):.3f}), vs "
        + ", ".join(f"{b} ({val(b, 'pooled', 'pr_auc'):.3f})" for b in ranked[1:]) + ".",
        f"Margin over runner-up {second}: {val(best, 'pooled', 'pr_auc') - val(second, 'pooled', 'pr_auc'):+.3f}; "
        f"CIs overlap: {val(second, 'pooled', 'pr_auc_ci_high') >= val(best, 'pooled', 'pr_auc_ci_low')}; "
        f"random floor {val('random_scorer', 'pooled', 'pr_auc'):.3f}; always-zero F1 is 0.",
        "Per-fold ranking can differ from pooled; do not over-read small gaps between baselines."]
md += ["", "## Summary", ""] + [f"{i + 1}. {s}" for i, s in enumerate(summ)]
(OUT / "baselines.md").write_text(insert_header(md, labels_header(HERE / "pairs_v2.csv", HERE / "folds.json", len(df), int(df.label.sum()))), encoding="utf-8")
print("\n".join(md))
